import base64, hmac, hashlib, json, subprocess

def b64u(b):
    return base64.urlsafe_b64encode(b).rstrip(b'=').decode()

def sign(payload, secret, alg='HS256'):
    h = {'alg': alg, 'typ': 'JWT'}
    seg = b64u(json.dumps(h, separators=(',',':')).encode()) + '.' + b64u(json.dumps(payload, separators=(',',':')).encode())
    sig = hmac.new(secret.encode(), seg.encode(), hashlib.sha256).digest()
    return seg + '.' + b64u(sig)

secret = 'devsecret'
binp = '/workspace/artifacts/target/jwt-verify'

# minimal token
for payload in [{}, {'sub':'x'}, {'role':'admin'}]:
    t = sign(payload, secret)
    r = subprocess.run([binp, '--token', t, '--key', secret], capture_output=True, text=True)
    print(repr(payload), '->', r.stdout.strip()[:300], r.stderr.strip()[:200])
EOF

